        return 0
    m = 0
    temp = n
    while temp > 0 and temp % 2 == 0:
        m += 1
        temp //= 2
    return temp

def check_condition(u, v):
    for k in range(v):
        n_start = u + k
        n_end = u + v + k

        f_start = f(n_start)
        f_end = f(n_end)

        difference = f_end - f_start

        if difference % 4 != 0:
            # print(f"Failure at u={u}, v={v}, k={k}. f(u+k)={f_start}, f(u+v+k)={f_end}. Difference={difference}")
            return False
    return True

